  const powerGuide={noodle:'Soup Slowdown briefly slows all falling items. Ingredient Magnet pulls food toward your bowl. Wok Sweep clears every chili bomb currently on screen. New powers unlock at Levels 4, 7, and 10.',match:'Kitchen Peek reveals the whole board for a moment. Fresh Shuffle remixes unmatched cards. Second Chance restores a heart. New powers unlock at Levels 4, 7, and 10.',roadster:'Turbo Brake slows traffic. Flavor Magnet collects tokens from any lane. Lane Shield blocks a crash. New powers unlock at Levels 4, 7, and 10.',trailblazer:'Lantern Hint shows your next tile. Route Preview briefly replays the route. Extra Time adds seconds to the current timer. New powers unlock at Levels 4, 7, and 10.',ace:'Focus slows the chopsticks. Wide Window temporarily enlarges the target. Second Chance restores a heart. New powers unlock at Levels 4, 7, and 10.',wok:'Wing Boost gives a stronger flap. Sky Shield absorbs one collision. Gate Gust clears the next gate. New powers unlock at Levels 4, 7, and 10.',lantern:'Dumpling Magnet pulls nearby food toward your snake. Slow Slither gives you time to steer across the open platform. Tail Shield protects you from one crash. New powers unlock at Levels 4, 7, and 10.',teatoss:'Paddle Extend widens your paddle. Slow Ball briefly slows the ball. Extra Heart restores one life. Some blocks drop a glowing extra charge when shattered; catch it with the paddle. New powers unlock at Levels 4, 7, and 10.',sugar:'Double Jump recharges your midair jump. Jade Shield blocks one hazard hit. Snack Magnet pulls nearby food to you. New powers unlock at Levels 4, 7, and 10.',mooncake:'Sesame Slowdown gives you more time to line up each layer. Extra Dough widens your current layer. Golden Tray safely catches one badly lined-up drop. New powers unlock at Levels 4, 7, and 10.'};
  const assetRoot='/assets/forbidden_bite/',sceneFiles={noodle:'arcade-noodle-mountain.webp',match:'arcade-dish-garden.webp',roadster:'arcade-roadster-food-market.jpg',trailblazer:'arcade-trail-garden.webp',ace:'arcade-ace-dim-sum.jpg',wok:'arcade-city-chongqing-night.jpg',lantern:'arcade-city-shanghai-park.jpg',teatoss:'arcade-city-street.jpg',sugar:'arcade-sugar-sprint-v2-ai.webp',mooncake:'arcade-mooncake-board-ai.webp?v=1'};
