  function awardPowerCharges(s,first=false){for(const power of powerDefs[mode])if(power.unlock<=s.level){if(s.powerCharges[power.id]===undefined)s.powerCharges[power.id]=1;else if(!first)s.powerCharges[power.id]=Math.min(3,s.powerCharges[power.id]+1)}}
  function levelGoalText(){if(!state)return'';if(state.endless)return mode==='wok'?'fly through lantern gates until you lose all hearts':mode==='mooncake'?'stack as many mooncake layers as you can until the run ends':mode==='lantern'?'collect dumplings and survive until a crash ends the run':'land perfect strikes until three timing misses end the run';if(mode==='noodle')return`catch ${state.goal} foods and avoid chili bombs`;if(mode==='match')return`match ${state.pairs} dish pairs · ${state.maxMoves-state.moves} moves left`;if(mode==='roadster')return`collect ${state.goalTokens} tokens in ${state.goalTime.toFixed(1)} seconds`;if(mode==='trailblazer')return`remember ${state.route.length} tiles · ${state.routeTime.toFixed(1)} seconds`;if(mode==='wok')return`pass ${state.gateGoal} lantern gates`;if(mode==='lantern')return state.snakeGateOpen?'guide the snake through the open exit gate':`collect ${state.snakeGoal} dumplings to open the exit gate`;if(mode==='sugar')return`collect ${state.sugarGoal} snacks and reach the rooftop gate`;if(mode==='mooncake')return`stack ${state.stackGoal} layers without dropping the filling`;if(mode==='teatoss')return`break ${state.bricksLeft} remaining blocks`;return`land ${state.goalHits} precise hits`}
  function levelBriefing(){const level=state?.level||nextLevel(),power=powerDefs[mode].find(item=>item.unlock===level);const notes={noodle:'Catch ingredients and dodge chili bombs; missed ingredients are safe. Use a power-up when a pepper wave gets crowded.',match:`The board has ${state?.pairs||Math.min(8,3+Math.floor(level/5))} pairs in Auto mode. It gains two tiles every fifth level; the opening preview gets extra study time at ten-level milestones.`,roadster:'Watch all three lanes: change lanes before trucks arrive, and collect tokens. Traffic speeds up in boss rounds.',trailblazer:`Study ${state?.route?.length||Math.min(21,4+Math.floor(level/6))} connected tiles, then retrace them in order. The preview gets extra time each ten-level milestone while routes still grow.`,ace:'Track the golden target arc and strike when the chopsticks cross it. Boss rounds increase speed; timing powers make the target easier to hit.',wok:'Tap to flap through lantern gaps. Gates move faster in boss rounds; shield and flap powers can help recover from a collision.',lantern:'Collect dumplings to unlock the exit, then guide the growing snake through it. Plan turns early to avoid the tail and platform edge.',teatoss:'Keep the ball in play and break every block. Later rounds add rows and tougher bricks; some shattered blocks drop catchable powers.',sugar:'Watch for roof spikes, falling stompers, and the floor saw. Stomper sides are safe; only a direct crusher hit hurts. Jump and use checkpoints.',mooncake:'Line up each moving layer with the tower. Overhang trims away; later levels move faster and boss rounds raise the stack goal.'};let text=notes[mode];if(level%10===0)text+=` Boss preview: ${bossNames[mode][Math.floor(level/10-1)%5]} appears this round.`;if(power)text+=` New power unlocked: ${power.label} — ${powerHelp[power.id]}`;$('level-briefing-title').textContent=`LEVEL ${level} BRIEFING${level%10===0?' · BOSS':''}`;$('level-briefing-copy').textContent=text}
  function syncHud(){$('stage-counter-label').textContent=state?.endless?'RUN COUNT':'LEVEL / GOAL';scoreEl.textContent=String(state?.score||0);livesEl.textContent=state?'♥'.repeat(state.lives)+'♡'.repeat(3-state.lives):'♥♥♥';clockEl.textContent=state?clockValue():`${nextLevel()} / 100`;bestEl.textContent=String(best[mode]||0);$('stage-kicker').textContent=state?(state.endless?`ENDLESS RUN · ${titles[mode].toUpperCase()}`:`LEVEL ${state.level} / 100${state.daily?' · DAILY CHALLENGE':state.practice?' · PRACTICE':state.boss?' · BOSS ROUND':''}`):'AVATAR CHALLENGE · 100 LEVELS';arcadeStage.dataset.boss=String(Boolean(state?.boss));arcadeStage.dataset.practice=String(Boolean(state?.practice));$('game-rule').textContent=state?(state.endless?`Endless Run · ${levelGoalText()}.`:`Level ${state.level}/100${state.boss?' · BOSS FIGHT':''} · ${levelGoalText()}.`):rules[mode];levelBriefing();syncMissionMeter()}
  function clockValue(){if(state.endless){if(mode==='wok')return`${state.gates} gates`;if(mode==='mooncake')return`${state.stackLayers.length-1} layers`;if(mode==='lantern')return`${state.snakeCollected} dumplings`;if(mode==='ace')return`${state.hits} hits`}if(mode==='noodle')return`${state.need}/${state.goal}`;if(mode==='match')return`${state.matched.size/2}/${state.pairs} pairs · ${Math.max(0,state.maxMoves-state.moves)} moves`;if(mode==='roadster')return`${Math.max(0,Math.ceil(state.goalTime-state.time))}s · ${state.tokens}/${state.goalTokens}`;if(mode==='trailblazer')return`${state.level}/100 · ${Math.max(0,Math.ceil(state.routeTime))}s`;if(mode==='wok')return`${state.gates}/${state.gateGoal} gates`;if(mode==='lantern')return state.snakeGateOpen?'GATE OPEN · ENTER TO CLEAR':`${state.snakeCollected}/${state.snakeGoal} dumplings`;if(mode==='sugar')return`${state.sugarCollected}/${state.sugarGoal} snacks`;if(mode==='mooncake')return`${state.stackLayers.length-1}/${state.stackGoal} layers`;if(mode==='teatoss')return`${state.bricksLeft} blocks`;return`${state.hits}/${state.goalHits}`}
  function updatePowerUI(){const select=$('power-select'),button=$('power-button'),quickbar=$('power-quickbar'),defs=powerDefs[mode],level=state?.level||1,current=selectedPower[mode];select.replaceChildren();quickbar.replaceChildren();for(const power of defs){const option=document.createElement('option');option.value=power.id;const locked=power.unlock>level,charges=state?.powerCharges?.[power.id]||0;option.textContent=locked?`${power.label} · unlock Level ${power.unlock}`:state?`${power.label} · ${charges} charge${charges===1?'':'s'}`:`${power.label} · ready at Level ${power.unlock}`;option.disabled=locked;select.append(option);const quick=document.createElement('button');quick.type='button';quick.className='power-quick';quick.disabled=locked||!state?.live||charges<1;const description=powerHelp[power.id]||'Use one saved charge for this round.';quick.setAttribute('aria-label',`${locked?`Locked until Level ${power.unlock}. `:''}${power.label.replace(/^\S+\s/, '')}: ${description}${locked?'':' '+charges+' charges available.'}`);quick.title=locked?`Unlock at Level ${power.unlock}`:`${description} One activation uses one charge; you can hold up to 3.`;quick.innerHTML=`<span class="power-quick-icon" aria-hidden="true">${power.label.match(/^\S+/)?.[0]||'✦'}</span><span>${power.label.replace(/^\S+\s/, '')}</span><b>${locked?'🔒':charges}</b><small class="power-description">${locked?`Unlock at Level ${power.unlock}`:description}</small>`;quick.classList.toggle('is-selected',power.id===current);quickbar.append(quick);quick.addEventListener('click',()=>{if(quick.disabled)return;selectedPower[mode]=power.id;select.value=power.id;powerUseFromButton()})}const firstAvailable=defs.find(power=>power.unlock<=level);if(!firstAvailable)return;const chosen=defs.find(power=>power.id===current&&power.unlock<=level)||firstAvailable;selectedPower[mode]=chosen.id;select.value=chosen.id;const charges=state?.powerCharges?.[chosen.id]||0;button.textContent=state?.awaitingNext?`Ready for Level ${state.level}`:state?`Use ${chosen.label} · ${charges} left`:`Choose a power-up during play`;button.disabled=!state?.live||charges<1}
  function powerUseFromButton(){const active=document.activeElement;if(active?.classList.contains('power-quick')){active.classList.remove('power-fired');void active.offsetWidth;active.classList.add('power-fired')}power();updatePowerUI()}
  function power(){if(!state?.live)return;const def=powerDefs[mode].find(item=>item.id===selectedPower[mode]);if(!def||def.unlock>state.level||!(state.powerCharges[def.id]>0))return;state.powerCharges[def.id]--;soundEffect('power');const s=state;tapEffect(480,270,mode==='lantern'?'#a8ffb8':'#ffe17b');let message='';if(def.id==='soupSlowdown'){s.powerUntil=s.time+4;message='Soup Slowdown: falling items are slower for 4 seconds.'}
    else if(def.id==='ingredientMagnet'){s.magnetUntil=s.time+4.5;message='Ingredient Magnet: the bowl will move toward food for 4.5 seconds.'}
    else if(def.id==='wokSweep'){for(const object of s.objects){if(object.bomb){object.hit=true;burst(object.x,object.y,'#e78b62',10)}}s.objects=s.objects.filter(object=>!object.hit);message='Wok Sweep cleared the chili bombs on screen.'}
    else if(def.id==='peekPair'){s.peekUntil=s.time+1.8;message='Kitchen Peek: every unmatched dish is showing briefly.'}
    else if(def.id==='shuffleCards'){const available=s.cards.map((_,i)=>i).filter(i=>!s.matched.has(i));const values=available.map(i=>s.cards[i]);for(let i=values.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[values[i],values[j]]=[values[j],values[i]]}available.forEach((index,i)=>s.cards[index]=values[i]);s.flipped=[];s.lockUntil=0;message='Fresh Shuffle: the unmatched dishes moved to new spots.'}
    else if(def.id==='turboBrake'){s.powerUntil=s.time+4;message='Turbo Brake slows the road for 4 seconds.'}
    else if(def.id==='flavorMagnet'){s.magnetUntil=s.time+5;message='Flavor Magnet collects tokens from any lane for 5 seconds.'}
    else if(def.id==='laneShield'){s.shield=true;message='Lane Shield will block your next crash.'}
    else if(def.id==='lanternHint'){s.hintUntil=s.time+2.4;message='Lantern Hint is lighting the next route tile.'}
    else if(def.id==='routePreview'){s.preview=Math.max(s.preview,2.8);message='Route Preview: study the glowing numbered path again.'}
    else if(def.id==='extraTime'){s.routeTime+=5;message='Extra Time added 5 seconds to this route.'}
    else if(def.id==='focus'){s.slowUntil=s.time+4;message='Focus slows the needle for 4 seconds.'}
    else if(def.id==='wideWindow'){s.wideWindowUntil=s.time+5;message='Wide Window enlarges the target for 5 seconds.'}
    else if(def.id==='wingFlap'){s.flapBoost=.85;flapBird(true);message='Wing Boost! Big lift — soar through the next gap.'}
    else if(def.id==='skyShield'){s.shield=true;message='Sky Shield will block one gate collision.'}
    else if(def.id==='gustClear'){const gate=s.pipes.sort((a,b)=>a.x-b.x)[0];if(gate){burst(gate.x,gate.top,'#d8f7a1',28);s.pipes=s.pipes.filter(pipe=>pipe!==gate)}message='A gust cleared the next lantern gate.'}
    else if(def.id==='snackMagnet'){s.magnetUntil=s.time+7;message='Dumpling Magnet pulls nearby snacks to your snake.'}
    else if(def.id==='snakeSlow'){s.slowUntil=s.time+6;message='Slow Slither gives you time to steer.'}
    else if(def.id==='snakeShield'){s.shield=true;message='Tail Shield will protect you from one crash.'}
    else if(def.id==='paddleExtend'){s.paddleWideUntil=s.time+8;message='Paddle Extend widens your paddle for eight seconds.'}
    else if(def.id==='ballSlow'){s.ballSlowUntil=s.time+6;message='Slow Ball makes shots easier to line up.'}
    else if(def.id==='secondChance'){s.lives=Math.min(3,s.lives+1);message='Second Chance restored one heart.'}
    else if(def.id==='creamJump'){s.extraJumpReady=true;message='Double Jump is ready. Tap jump again in midair!'}
    else if(def.id==='caramelShield'){s.shield=true;message='Jade Shield will block your next hazard hit or fall.'}
    else if(def.id==='sprinkleMagnet'){s.magnetUntil=s.time+8;message='Snack Magnet is pulling nearby food toward you.'}
    else if(def.id==='sesameSlow'){s.stackSlowUntil=s.time+5;message='Sesame Slowdown gives the moving mooncake more time for five seconds.'}
    else if(def.id==='extraDough'){s.layer.w=Math.min(360,s.layer.w+48);s.layer.x=clamp(s.layer.x-24,55,905-s.layer.w);message='Extra Dough widened your moving layer by 48 pixels.'}
    else if(def.id==='goldenTray'){s.stackAssist=true;message='Golden Tray is ready to catch one missed layer.'}
    else if(def.id==='brothGuard'){s.shield=true;message='Broth Guard will stop the next chili bomb.'}
    else if(def.id==='memoryBloom'){s.peekUntil=s.time+3;message='Memory Bloom reveals unmatched dishes for three seconds.'}
    else if(def.id==='marketCruise'){s.powerUntil=s.time+6;s.magnetUntil=s.time+6;message='Market Cruise slows traffic and attracts flavor tokens for six seconds.'}
    else if(def.id==='longLanternPreview'){s.preview=Math.max(s.preview,4.5);message='Long Lantern Preview: study the full route again.'}
    else if(def.id==='goldenEncore'){s.slowUntil=s.time+5;s.wideWindowUntil=s.time+5;message='Golden Encore slows the chopsticks and widens the target for five seconds.'}
    else if(def.id==='phoenixFlap'){s.shield=true;s.flapBoost=.85;flapBird(true);message='Phoenix Flap gives a strong lift and protects against one collision.'}
    else if(def.id==='jadeCoil'){s.slowUntil=s.time+7;s.magnetUntil=s.time+7;message='Jade Coil slows your snake and attracts dumplings for seven seconds.'}
    else if(def.id==='teaService'){s.paddleWideUntil=s.time+8;s.ballSlowUntil=s.time+6;message='Tea Service widens the paddle and slows the ball.'}
    else if(def.id==='roofSpring'){s.extraJumpReady=true;s.shield=true;message='Roof Spring recharges a jump and blocks one hazard hit.'}
    else if(def.id==='sweetSpot'){s.layer.w=Math.min(360,s.layer.w+40);s.layer.x=clamp(s.layer.x-20,55,905-s.layer.w);s.stackAssist=true;message='Sweet Spot widened this layer and will catch one missed alignment.'}
    else if(def.id==='sesameSlow'){s.stackSlowUntil=s.time+5;message='Sesame Slowdown gives the moving mooncake more time for five seconds.'}
    else if(def.id==='extraDough'){s.layer.w=Math.min(360,s.layer.w+48);s.layer.x=clamp(s.layer.x-24,55,905-s.layer.w);message='Extra Dough widened your moving layer by 48 pixels.'}
    else if(def.id==='goldenTray'){s.stackAssist=true;message='Golden Tray is ready to catch one missed layer.'}
    statusEl.textContent=message;syncHud();updatePowerUI()}
  function end(win,reason){if(!state||!state.live)return;const score=state.score;if(!win&&!state.practice&&state.time>=20&&window.ForbiddenBiteCollection){const earned=window.ForbiddenBiteCollection.award(1,"Arcade participation",state.walletRun+"-finish");if(earned)reason+=" You earned "+earned+" Bite Point for playing."}if(state.practice&&!win){state.score=0;state.streak=0;state.lives=3;configureLevel(state,state.level);state.powerCharges={};awardPowerCharges(state,true);state.live=true;overlay.hidden=true;statusEl.textContent=`Practice retry · ${reason} No hearts or progress lost.`;syncHud();updatePowerUI();drawScene(0);return}runToken++;state.live=false;state.awaitingNext=false;if(!state.practice&&!state.daily&&score>(best[mode]||0)){best[mode]=score;saveBest();soundEffect('record')}syncHud();updatePowerUI();renderRecords();$('overlay-kicker').textContent=state.endless?'ENDLESS RUN OVER':win?(state.daily?'DAILY CHALLENGE CLEARED':'100 LEVELS CLEARED'):'RUN OVER';$('overlay-title').textContent=state.endless?'Run complete!':win?'Arcade legend!':'The kitchen got you.';$('overlay-copy').textContent=state.endless?`${reason} You cleared ${mode==='wok'?state.gates+' gates':mode==='mooncake'?Math.max(0,state.stackLayers.length-1)+' layers':mode==='lantern'?state.snakeCollected+' dumplings':state.hits+' perfect hits'}. Final score: ${score}. Personal best: ${best[mode]||0}. Tap Endless Run to try again.`:`${reason} Final score: ${score}${state.practice?' · Practice scores do not affect records':''}. Personal best score: ${best[mode]||0}; highest level cleared: ${bestLevel[mode]||0}.`;const b=$('start-game');b.textContent=win?`Play ${titles[mode]} again · Level 1`:`Continue ${titles[mode]} · Level ${nextLevel()}`;if(state.endless)$('endless-game').textContent=`Play ${titles[mode]} Endless Again`;overlay.hidden=false;statusEl.textContent=win?(state.daily?`${titles[mode]} daily challenge complete!`:`${titles[mode]} cleared all 100 levels. Personal best score: ${best[mode]||0}; highest level cleared: ${bestLevel[mode]||0}.`):`${titles[mode]} ended. ${reason}`;drawScene(0);b.focus({preventScroll:true})}
  function clearLevel(reason){const s=state;if(!s?.live)return;soundEffect('clear');const cleared=s.level;addScore(200+cleared*40);if(s.daily){const earned=window.ForbiddenBiteCollection?.award(4,"Arcade daily clear",s.walletRun+"-daily");if(earned)reason+=" +"+earned+" Bite Points!";dailyDone[`${s.dailyDate}:${mode}`]=true;saveStore(dailyKey,dailyDone);awardBadge(mode,'daily');awardBadge(mode,'first');if(s.boss)awardBadge(mode,'boss');refreshDailyButton();burst(480,270,'#ffd35e',72);end(true,`${reason} Today’s ${titles[mode]} challenge is complete.`);return}if(s.practice){s.live=false;s.awaitingNext=true;configureLevel(s,cleared);s.powerCharges={};awardPowerCharges(s,true);$('overlay-kicker').textContent='PRACTICE ROUND CLEARED';$('overlay-title').textContent='Nice run. Try it again?';$('overlay-copy').textContent=`${reason} Practice does not change your saved level or record.`;$('start-game').textContent=`Replay Practice Level ${cleared}`;overlay.hidden=false;statusEl.textContent=`Practice Level ${cleared} complete. Your progress and records are unchanged.`;syncHud();updatePowerUI();drawScene(0);return}recordBestLevel(cleared);const earned=window.ForbiddenBiteCollection?.award(cleared%10===0?5:3,"Arcade level",s.walletRun+"-level-"+cleared);if(earned)reason+=" +"+earned+" Bite Points!";awardBadge(mode,'first');if(cleared%10===0)awardBadge(mode,'boss');if(cleared>=100){progress[mode]=1;saveProgress();syncModeBadges();if(s.boss){burst(480,270,'#ffd35e',72);burst(410,300,'#71e7b3',48)}end(true,`${reason} You defeated all ten bosses and completed all 100 levels.`);return}progress[mode]=cleared+1;saveProgress();syncModeBadges();runToken++;s.live=false;s.level=cleared+1;s.lives=Math.min(3,s.lives+1);configureLevel(s,s.level);if(s.boss){burst(480,270,'#ffd35e',42);burst(410,300,'#71e7b3',28)}awardPowerCharges(s);s.awaitingNext=true;const unlocked=powerDefs[mode].find(power=>power.unlock===s.level),boss=s.level%10===0,bossName=boss?bossNames[mode][Math.floor(s.level/10-1)%5]:'';$('overlay-kicker').textContent=boss?'BOSS ROUND AHEAD':unlocked?`NEW POWER-UP · LEVEL ${s.level}`:`LEVEL ${cleared} COMPLETE`;$('overlay-title').textContent=boss?`${bossName} is waiting!`:`Level ${cleared} cleared!`;$('overlay-copy').textContent=`${reason} You earned a heart and your unlocked powers gained a charge. Next: Level ${s.level} of 100 — ${levelGoalText()}.${boss?` Boss ${s.level/10}: ${bossName} brings a tougher challenge.`:''}${unlocked?` New power unlocked: ${unlocked.label}.`:''}`;$('start-game').textContent=`Start Level ${s.level}`;overlay.hidden=false;if(boss)soundEffect('boss');statusEl.textContent=`Level ${cleared} complete. ${boss?`Boss ${s.level/10} is next: ${bossName}. `:''}${unlocked?`${unlocked.label} unlocked. `:''}Prepare for Level ${s.level}.`;syncHud();updatePowerUI();drawScene(0);$('start-game').focus({preventScroll:true})}
  function hurt(message){if(!state?.live)return;soundEffect('hit');state.streak=0;state.shake=.22;const x=mode==='match'?480:mode==='roadster'?272+state.lane*208:mode==='trailblazer'?264+(state.cell%5)*88+40:mode==='lantern'?40+(state.snake[0].x+.5)*40:mode==='teatoss'?state.ball.x:mode==='wok'?state.birdX:mode==='sugar'?state.sugarPlayer.x-state.sugarCamera+17:mode==='ace'?480+Math.cos(state.angle)*170:state.playerX||480,y=mode==='match'?275:mode==='roadster'?462:mode==='trailblazer'?54+Math.floor(state.cell/5)*88+40:mode==='lantern'?40+(state.snake[0].y+.5)*40:mode==='teatoss'?state.ball.y:mode==='wok'?state.birdY:mode==='sugar'?state.sugarPlayer.y+20:mode==='ace'?282+Math.sin(state.angle)*170:450;burst(x,y,'#ef7469',14);if(state.practice){statusEl.textContent=`Practice: ${message} No heart lost.`;syncHud();return}state.lives--;statusEl.textContent=message;if(state.lives<=0)end(false,message);syncHud()}
  function addScore(n=1){state.score+=n;syncHud()}function scorePoint(){const s=state;if(mode==='noodle')return{x:s.playerX,y:420};if(mode==='match')return{x:480,y:275};if(mode==='roadster')return{x:272+(s.laneX??s.lane)*208,y:425};if(mode==='trailblazer')return{x:304+(s.cell%5)*88,y:88+Math.floor(s.cell/5)*88};if(mode==='wok')return{x:s.birdX,y:s.birdY};if(mode==='lantern')return{x:((960-s.snakeCols*36)/2)+(s.snake[0].x+.5)*36,y:48+(s.snake[0].y+.5)*36};if(mode==='teatoss')return{x:s.ball.x,y:s.ball.y};if(mode==='sugar')return{x:s.sugarPlayer.x-s.sugarCamera+17,y:s.sugarPlayer.y+20};if(mode==='mooncake')return{x:s.layer.x+s.layer.w/2,y:s.layer.y+(s.stackLift||0)};return{x:480+Math.cos(s.angle)*150,y:282+Math.sin(s.angle)*150}}function awardSkillScore(base){soundEffect('pickup');state.streak=(state.streak||0)+1;const bonus=Math.min(state.streak-1,8)*25,points=base+bonus,{x,y}=scorePoint();addScore(points);state.floaters??=[];state.floaters.push({x,y:y-12,vx:(Math.random()-.5)*24,age:0,life:.82,text:bonus?`+${points}  ·  COMBO ×${state.streak}`:`+${points}`,color:state.streak>=4?'#fff0a1':'#f8d46b'});if(state.floaters.length>18)state.floaters.shift();state.ripples.push({x,y,color:state.streak>=4?'#f2d26a':'#7bd28a',age:0});if(state.streak>1&&state.streak%4===0){tapEffect(x,y,'#f4d56b');burst(x,y,'#f4d56b',22)}return bonus}
